// A chaining hash map: one array of buckets, each a list of [key, value] pairs.
const HASHES = {
  djb2: s => { let h = 5381; for (let i = 0; i < s.length; i++) h = ((h * 33) ^ s.charCodeAt(i)) >>> 0; return h; },
  charsum: s => { let h = 0; for (let i = 0; i < s.length; i++) h += s.charCodeAt(i); return h; },
  length: s => s.length,
};

class HashMap {
  constructor({ buckets = 8, hash = 'djb2', maxLoad = 0 } = {}) {
    this.buckets = Array.from({ length: buckets }, () => []);
    this.hash = HASHES[hash];
    this.maxLoad = maxLoad;      // 0 = never resize
    this.size = 0;
    this.resizes = 0;
  }
  bucketIndex(key) {
    return this.hash(String(key)) % this.buckets.length;
  }
  set(key, value) {
    let bucket = this.buckets[this.bucketIndex(key)];
    const hit = bucket.find(e => e[0] === key);
    if (hit) { hit[1] = value; return this; }
    if (this.maxLoad && (this.size + 1) / this.buckets.length > this.maxLoad) {
      this.resize(this.buckets.length * 2);
      bucket = this.buckets[this.bucketIndex(key)];
    }
    bucket.push([key, value]);
    this.size++;
    return this;
  }
  resize(count) {
    const old = this.buckets;
    this.buckets = Array.from({ length: count }, () => []);
    this.resizes++;
    for (const chain of old) for (const entry of chain) this.buckets[this.bucketIndex(entry[0])].push(entry);
  }
  get(key, fallback) {
    const hit = this.buckets[this.bucketIndex(key)].find(e => e[0] === key);
    return hit ? hit[1] : fallback;
  }
  delete(key) {
    const bucket = this.buckets[this.bucketIndex(key)];
    const i = bucket.findIndex(e => e[0] === key);
    if (i === -1) return false;
    bucket.splice(i, 1);
    this.size--;
    return true;
  }
  stats() {
    let checks = 0, longest = 0, empty = 0;
    for (const chain of this.buckets) {
      longest = Math.max(longest, chain.length);
      if (!chain.length) empty++;
      for (let j = 0; j < chain.length; j++) checks += j + 1;
    }
    return { load: this.size / this.buckets.length, avgChecks: this.size ? checks / this.size : 0, longest, empty };
  }
}

const prices = new HashMap({ buckets: 8, maxLoad: 0.75 });
prices.set('apple', 0.4).set('banana', 0.25).set('cherry', 3.5).set('date', 2.1);
console.log('banana costs', prices.get('banana'));
console.log('missing key ->', prices.get('kiwi', 'not stocked'));
prices.set('banana', 0.3);                       // update in place
console.log('banana now costs', prices.get('banana'));
prices.delete('date');
console.log('after delete, size =', prices.size);

const show = () => prices.buckets.forEach((b, i) => {
  if (b.length) console.log('  bucket ' + i + ':', b.map(e => e[0]).join(', '));
});
console.log('\nwith ' + prices.buckets.length + ' buckets:');
show();

for (const fruit of ['elderberry', 'fig', 'grape', 'kiwi']) prices.set(fruit, 1);
console.log('\nadded 4 more: ' + prices.size + ' keys, so it doubled to ' + prices.buckets.length +
  ' buckets (' + prices.resizes + ' resize):');
show();
const s = prices.stats();
console.log('load ' + s.load.toFixed(2) + ', average keys checked ' + s.avgChecks.toFixed(2) + ', longest chain ' + s.longest);

