// Average keys checked per lookup as the map fills, for five set-ups.
const HASHES = {
  djb2: s => { let h = 5381; for (let i = 0; i < s.length; i++) h = ((h * 33) ^ s.charCodeAt(i)) >>> 0; return h; },
  charsum: s => { let h = 0; for (let i = 0; i < s.length; i++) h += s.charCodeAt(i); return h; },
  length: s => s.length,
};
const setups = [
  { name: 'djb2, never resize', hash: 'djb2', limit: 0 },
  { name: 'djb2, resize at 0.75', hash: 'djb2', limit: 0.75 },
  { name: 'sum of letters, resize at 0.75', hash: 'charsum', limit: 0.75 },
  { name: 'length, resize at 0.75', hash: 'length', limit: 0.75 },
];
const MAX = 256, START = 8;

const rows = [];
const table = {};
for (const s of setups) {
  const hash = HASHES[s.hash];
  let buckets = Array.from({ length: START }, () => []);
  for (let i = 0; i < MAX; i++) {
    if (s.limit && (i + 1) / buckets.length > s.limit) {     // same rule as the class
      const old = buckets;
      buckets = Array.from({ length: old.length * 2 }, () => []);
      for (const chain of old) for (const k of chain) buckets[hash(k) % buckets.length].push(k);
    }
    const key = 'user:' + (i + 1) * 7919;
    buckets[hash(key) % buckets.length].push(key);
    const n = i + 1;
    if (n % 8 === 0) {
      let checks = 0, longest = 0;
      for (const chain of buckets) { longest = Math.max(longest, chain.length); checks += chain.length * (chain.length + 1) / 2; }
      rows.push({ keys: n, checks: checks / n, setup: s.name });
      if (n === 64 || n === 256) table[s.name + n] = { checks: checks / n, longest, buckets: buckets.length };
    }
  }
}
for (let n = 8; n <= MAX; n += 8) rows.push({ keys: n, checks: 1 + n / START / 2, setup: 'theory 1 + load/2, 8 buckets' });

console.log('set-up                            keys  buckets  avg checks  longest chain');
for (const s of setups) for (const n of [64, 256]) {
  const t = table[s.name + n];
  console.log(s.name.padEnd(32) + String(n).padStart(6) + String(t.buckets).padStart(9) +
    t.checks.toFixed(2).padStart(12) + String(t.longest).padStart(15));
}

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 300,
  title: 'Keys checked per lookup as the map fills',
  data: { values: rows },
  mark: { type: 'line', strokeWidth: 2 },
  encoding: {
    x: { field: 'keys', type: 'quantitative', title: 'keys inserted' },
    y: { field: 'checks', type: 'quantitative', scale: { type: 'log' }, title: 'average keys checked (log scale)' },
    color: { field: 'setup', type: 'nominal', title: null },
    strokeDash: { condition: { test: "indexOf(datum.setup, 'theory') === 0", value: [5, 4] }, value: [1, 0] },
  },
};
